INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5b91f798-3e42-40ec-9630-f8b5f9be7306', '21feff02-016d-46e2-bb9d-c27495133b1b', '130. óra: Az egész számokról tanultak összefoglalása, vegyes feladatok', 'Év végi ismétlés: műveletek egész számokkal, előjelek, abszolút érték, ellentett.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "f32d4077-251b-4104-91e1-2a809eb38d61", "text": "Mennyi (-15) + (+25)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "fce814da-0620-4f53-8a6a-ffd73fb4dce3", "text": "Mennyi (-8) * (-7)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "56"}, {"id": "9ed34547-88a7-407e-b23d-1dc8694d3383", "text": "Mennyi (-63) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-7"}, {"id": "d97abc1c-e4f7-41cd-8e25-5d0e8369c9f6", "text": "Két negatív szám szorzata mindig pozitív.", "type": "true-false", "options": [{"id": "f95615ca-b4f8-4f2e-b4e2-dd83503c9347", "text": "Igaz", "isCorrect": true}, {"id": "a9047812-5a6c-4ca5-8e57-2b56899ecfbf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "17a053d9-d6e0-4406-9f0d-142f26c12300", "text": "Mennyi |-40|?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "7ef80fe2-9d9b-4e84-b37d-cfda02cbb26e", "text": "Melyik szám nagyobb: -12 vagy -4?", "type": "multiple-choice", "options": [{"id": "372852a3-1ddd-4911-9260-9ea575503be1", "text": "-4", "isCorrect": true}, {"id": "79d99422-c7ee-403f-adbd-25329458904f", "text": "-12", "isCorrect": false}, {"id": "a6fb956e-cec7-4951-b7d4-01eeb1f17cae", "text": "Egyenlők", "isCorrect": false}, {"id": "385bdacf-dbed-438a-922e-458d46a453b6", "text": "Nem eldönthető", "isCorrect": false}], "timeLimit": 15}, {"id": "676cb7ae-d595-4146-8b66-aaf5038a7574", "text": "Mennyi (-5) * (-2) * (-3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-30"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('35923c7e-b81f-4cd2-801c-2b5394bb5048', '21feff02-016d-46e2-bb9d-c27495133b1b', '131. óra: Az oszthatóságról tanultak összefoglalása', 'Év végi ismétlés: oszthatósági szabályok, prímek, lkkt és lnko.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "c220acce-d00e-42bf-b67b-a0adf798bf7a", "text": "Osztható-e a 435 5-tel és 3-mal is (azaz 15-tel)?", "type": "true-false", "options": [{"id": "e0fe769f-107c-4718-a18f-6b28aba6468f", "text": "Igaz (5-re végződik és 4+3+5=12)", "isCorrect": true}, {"id": "1ef721b9-2c95-4c61-aafa-afb8dbc487ed", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7a0eaba6-23cc-486c-a607-9ae25f84a870", "text": "Osztható-e a 612 4-gyel?", "type": "true-false", "options": [{"id": "cd4e9006-01a2-44a7-821d-354758a9fa8c", "text": "Igaz (12 osztható 4-gyel)", "isCorrect": true}, {"id": "a1cc1490-231d-48c5-a9ac-69b8feeade7d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "57830753-9123-4a94-96b6-d2e74095ad87", "text": "Mennyi lkkt(6, 8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "e45d446f-d1ea-43de-80c9-7f159e92ca61", "text": "Mennyi lnko(12, 18)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "521e704f-631b-44d1-a1a9-fc3c767923cf", "text": "Melyik a legkisebbkétjegyű prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "7c126be9-dda2-420d-9516-09dd01279415", "text": "A 2 az egyetlen páros prímszám.", "type": "true-false", "options": [{"id": "25debe45-af36-42c8-be83-5792d59d830a", "text": "Igaz", "isCorrect": true}, {"id": "146ff0b8-e950-4d15-8044-e0ccdafd76b7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "48a4ead4-c414-40bb-bef7-3e861e69ba2f", "text": "Melyik szám osztható 9-cel?", "type": "multiple-choice", "options": [{"id": "f97f114d-6d11-496b-854d-80369eda7335", "text": "819 (8+1+9=18)", "isCorrect": true}, {"id": "441b4507-5d64-4640-aa37-26982710edd6", "text": "815", "isCorrect": false}, {"id": "7d72b80e-4c18-447b-af5c-e5cb1dc759e3", "text": "812", "isCorrect": false}, {"id": "3b774ae9-6784-49c7-8179-735a2ce43b56", "text": "811", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('09859305-dc39-410b-a491-46ce2e2a7f95', '21feff02-016d-46e2-bb9d-c27495133b1b', '132. óra: A törtekről tanultak összefoglalása, vegyes feladatok', 'Év végi ismétlés: közönséges és tizedes törtek műveletei.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "d9da4e95-ce27-4998-84eb-80eff25199b2", "text": "Mennyi 3/4 + 1/2? (3/4 + 2/4)", "type": "multiple-choice", "options": [{"id": "1932965b-bbdf-4b05-8195-79543aa6881d", "text": "5/4 (1 egész 1/4)", "isCorrect": true}, {"id": "241083d5-e6c2-474a-94d1-46e9c0d20605", "text": "4/6", "isCorrect": false}, {"id": "e21869b3-8737-48af-bcc2-26d2e2e64c09", "text": "4/4", "isCorrect": false}, {"id": "14a29b67-0acf-4a12-b398-7063ee141789", "text": "3/8", "isCorrect": false}], "timeLimit": 15}, {"id": "ca2f706c-6223-4a42-9824-0d9416c798fa", "text": "Mennyi 2/3 * 3/5?", "type": "multiple-choice", "options": [{"id": "bab21587-e597-4a9f-a7d5-6eec07de9def", "text": "2/5", "isCorrect": true}, {"id": "5b62b89a-fcab-4c06-9f3d-cae454c41a25", "text": "6/15", "isCorrect": false}, {"id": "f84e5907-c78a-48e1-864e-771d9d5317c8", "text": "5/8", "isCorrect": false}, {"id": "33d9661d-51b0-407f-9984-f24e68fdef4b", "text": "6/8", "isCorrect": false}], "timeLimit": 15}, {"id": "a6eed133-c337-49e0-ac1c-8d9d8836b65b", "text": "Mennyi 1/2 : 1/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "1d7c8c81-abcb-470d-9f8e-4e215ab87b42", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "398ad9d0-893d-4866-8c41-bbf991837272", "text": "Mennyi 4,8 : 0,6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "d936b6ba-3473-42c5-84c5-38e2dd7c6440", "text": "A 0,75 megegyezik a 3/4 törttel.", "type": "true-false", "options": [{"id": "69d7ca25-cd37-467a-a969-769155d96746", "text": "Igaz", "isCorrect": true}, {"id": "0c419b94-f93a-4dab-bf85-2b9fae863253", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "91d91394-b513-4a63-80d1-07dff01bb7c5", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5b3f8c0b-0e18-4861-b59d-f78ddf8f4410', '21feff02-016d-46e2-bb9d-c27495133b1b', '133. óra: A geometriai ismeretek összefoglalása, vegyes feladatok', 'Év végi ismétlés: szögek, alakzatok, tengelyes tükrözés.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "3316cfe4-4aa5-4d66-b77b-82a1106e662a", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "3fb3f786-e371-4d3f-b687-45f37bdeb698", "text": "Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "0bed702d-d90d-4f0c-b51f-4c2d0ee7c049", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "b5e6f7f3-85e9-4d9f-b97e-80eacf84ce0a", "text": "Ha a kör sugara 6 cm, mekkora az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "d27d10d4-595a-43aa-8b01-d289de787838", "text": "A tengelyes tükrözés távolságtartó transzformáció.", "type": "true-false", "options": [{"id": "d7179d24-b09c-4574-a365-c89864e33b27", "text": "Igaz", "isCorrect": true}, {"id": "b610cc1f-b148-453a-84cc-9f9eb51efad9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "49973813-b02a-4281-b1a1-b544fef6aa18", "text": "Hány fokos szöget zár be a szakaszfelező merőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "23eb3863-94b0-456c-8fad-0305950d2aa3", "text": "Milyen szög a 90°-os szög?", "type": "multiple-choice", "options": [{"id": "7a1c8c98-059f-4dfa-8267-9c1df9d4dbfb", "text": "Derékszög", "isCorrect": true}, {"id": "91cd8ec6-e0bd-43c2-939e-f3b6bb7b65b0", "text": "Hegyesszög", "isCorrect": false}, {"id": "8bbc1739-ddc8-46a6-9a69-120348afbdec", "text": "Tompaszög", "isCorrect": false}, {"id": "066d9b45-8b48-4f87-87d1-a6865d995ee2", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7cd58e92-7d93-4ebe-a88f-bca83bac2662', '21feff02-016d-46e2-bb9d-c27495133b1b', '134. óra: Arányosság, százalék, szöveges feladatok', 'Év végi ismétlés: egyenes arányosság, százalékszámítás, nyitott mondatok.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "614dbf1a-4392-4b3f-a1e3-7f50f8a5a41d", "text": "Ossz el 500 Ft-ot 2 : 3 arányban! Hány Ft a kisebbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "51994c1b-2082-4be0-82ed-c13edec20398", "text": "Ha 3 kg narancs 1200 Ft, mennyibe kerül 7 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2800"}, {"id": "4cc77852-b1f7-4535-b865-8b8dceb9450c", "text": "Mennyi 4000 Ft-nak a 20%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "800"}, {"id": "1e4a0c58-4808-4f9d-b410-824d9d9f0d41", "text": "Melyik szám teszi igazzá: 3 * x + 5 = 26? (21/3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "bda56647-6593-4624-a716-1d38bd1f834a", "text": "Gondoltam egy számot, elosztottam 4-gyel, hozzáadtam 6-ot, 11-et kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "88f80383-119c-4170-8f7b-52eddb5be17a", "text": "Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "adc05fb4-c778-419f-a1cb-e62323aedc2e", "text": "Igaz", "isCorrect": true}, {"id": "acd7ec25-8843-4f8b-a341-0736d626a0e6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "be427c6d-12b9-410e-bf60-0748843032f1", "text": "Hány százalék felel meg a 4/5 törtszám teljes értékének?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "80"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8675807d-17b8-4b30-b6cb-89a0b647da94', '21feff02-016d-46e2-bb9d-c27495133b1b', '135. óra: A hosszúság, a kerület, a terület és a térfogat fogalmával kapcsolatos feladatok', 'Év végi ismétlés: mérések, kerület, terület, felszín, térfogat.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "048b2999-8a43-42d0-9792-39c882054359", "text": "Mennyi a 6 cm és 5 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "535b4c2a-7760-4dab-a176-5cf78946a39f", "text": "Mennyi a 6 cm és 5 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "5da9db14-939e-44e6-9f70-5ce123b5b98a", "text": "Mennyi a 4 cm élű kocka felszíne? (6 * 16)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "8fa5dd83-9e20-400b-bf78-24c8ba0cfa0b", "text": "Mennyi a 4 cm élű kocka térfogata? (4 * 4 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "2ba17716-9883-4cf7-bfe0-9da53378aba7", "text": "1 liter víz térfogata 1 dm³.", "type": "true-false", "options": [{"id": "bb9ca3bd-9202-4b9a-a99d-851d779585c9", "text": "Igaz", "isCorrect": true}, {"id": "10ce7a21-23d6-4f58-841d-b4c009e0989e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cf5d8b2a-ff94-4e5e-bcdb-8af8ee213b44", "text": "Hány cm³ 1 dm³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "fb4044dd-7d23-4d16-969c-e71d16bd1769", "text": "Hány mm² 1 cm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('53d19c8f-dfed-4427-a1dd-e023bed7e334', '21feff02-016d-46e2-bb9d-c27495133b1b', '136. óra: Az éves munka értékelése', 'Az 6. osztályos matematika törzsanyag sikeres teljesítésének záró értékelése.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "3f8272b6-e207-4fac-9336-dc31797f5680", "text": "Mely főbb témaköröket dolgoztuk fel a 6. osztályos matematika tananyagban?", "type": "multiple-choice", "options": [{"id": "59ca5924-f18c-465b-9ba6-01fefc3f234d", "text": "Egész számok, oszthatóság, törtek, geometria, arány és százalék, kerület-terület-felszín-térfogat, statisztika, pénzügyek", "isCorrect": true}, {"id": "b1b73109-d0ca-42de-a331-8797aaf20607", "text": "Kizárólag geometria", "isCorrect": false}, {"id": "62e933e7-993e-4c86-8774-c270c6cb24d3", "text": "Kizárólag rajzolás", "isCorrect": false}, {"id": "b503195e-5adb-4dbd-837c-2ef6f75caba7", "text": "Csak az 1. osztályos ismétlés", "isCorrect": false}], "timeLimit": 15}, {"id": "99631965-29c4-4048-b010-6d8019f35065", "text": "A szorgalmas felkészülés és a rendszerezett gyakorlás a matematikai tudás alapja.", "type": "true-false", "options": [{"id": "0b392ce6-9f78-49dd-886d-d440de558e1f", "text": "Igaz", "isCorrect": true}, {"id": "d5b17633-c6f8-4396-b8f2-5a5f15259b6d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "edacedbf-6518-4910-bfe3-5e245ce0fb6d", "text": "Hány órából állt a 6. osztályos teljes matematika tananyag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "136"}, {"id": "3067f92a-6503-453a-a7b6-c2cb76330bbf", "text": "A megszerzett matematikai tudás segít a mindennapi pénzügyekben és a döntéshozatalban.", "type": "true-false", "options": [{"id": "05e1b709-eaf5-4d91-90de-232cecd0941b", "text": "Igaz", "isCorrect": true}, {"id": "89b8e47a-675b-463d-adde-cdcf0b50ec85", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "57923dfa-348a-4ba4-8925-60d1336b429e", "text": "Gratulálunk a 6. osztályos matematika tananyag sikeres teljesítéséhez!", "type": "true-false", "options": [{"id": "2f97b678-66a2-422a-b71d-ebb3623db2cd", "text": "Igaz", "isCorrect": true}, {"id": "1223cc1d-8de8-4220-91d3-94ef3bb5c7ac", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5e456180-ae34-4e9e-b0c8-80b1e4c28eab", "text": "A 7. osztályban az itt megszerzett alapokra (pl. oszthatóság, törtek, százalék, geometria) építünk tovább.", "type": "true-false", "options": [{"id": "f34ca79d-9915-43da-b774-a9d06028687d", "text": "Igaz", "isCorrect": true}, {"id": "fc80d471-fe0d-4d48-a4fc-00b02c04391a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e45ffad2-fe6a-4002-b2fc-7811234c11b2", "text": "Melyik volt a kedvenc témaköröd ebben a tanévben?", "type": "multiple-choice", "options": [{"id": "f4b11de1-f7ba-43b7-b48c-dd241a74f1c3", "text": "Mindegyik témakör hasznos és érdekes volt!", "isCorrect": true}, {"id": "875a826e-99c2-4796-986b-89b554d18989", "text": "Egész számok és oszthatóság", "isCorrect": false}, {"id": "feb89f18-70ac-45e3-a2e5-6cc376e7ab84", "text": "Geometria és tengelyes tükrözés", "isCorrect": false}, {"id": "7dbb0ea9-742b-4c7c-9452-f1f95010b75e", "text": "Arányosság és százalékszámítás", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());